"""The displayed interlock is generated by the same update that sets flap targets."""
import math

from vtx.phantom.plant import PhantomAircraft
from vtx.world import TestWorld


def test_flap_limit_reports_physics_override_and_preserves_the_pilot_command():
    world = TestWorld()
    aircraft = PhantomAircraft(world, 'phantom-a10c', start_configuration='road')
    aircraft.spawn(0, 0, world.surface_z(0, 0))
    aircraft.wing_state = {'left': 'locked', 'right': 'locked'}
    aircraft.set_command({'flap_deg': [30.0, 30.0]})
    for side in ('left', 'right'):
        aircraft.targets[f'flap_{side}'] = math.radians(30)
    aircraft.data.qvel[0] = 76.0
    aircraft.control_update(.01)
    interlock = aircraft.physical_snapshot()['phantom']['flap_interlock']
    assert interlock['max_speed_m_s'] == 75
    assert interlock['reasons'] == ['airspeed_limit', 'airspeed_limit']
    assert aircraft.command['flap_deg'] == [30.0, 30.0]
    assert aircraft.targets['flap_left'] < math.radians(30)
